"use strict";exports.formatMedicines=function(r){if(!r)return[];let t=r;if("string"==typeof t){const r=t.trim();if(!r)return[];try{const e=JSON.parse(r);t=Array.isArray(e)?e:[r]}catch(e){t=r.split(/\n|；|;/).filter((r=>r.trim()))}}return Array.isArray(t)?t.map((r=>{if(r&&"object"==typeof r)return{name:String(r.name||r.medicine||r.title||"未命名药剂"),usage:String(r.usage||r.use||r.method||r.desc||""),tox:String(r.tox||"")};const t=String(r||"").trim(),e=t.match(/^([^\s，,：:（(]+)[\s，,：:（(]+(.*)$/);return e?{name:e[1],usage:e[2]}:{name:t,usage:""}})).filter((r=>r.name)):[]},exports.toStringList=function(r){if(!r)return[];if("string"==typeof r){const e=r.trim();if(!e)return[];try{const r=JSON.parse(e);return Array.isArray(r)?r.map((r=>String(r))):[e]}catch(t){return e.split(/\n/).map((r=>r.trim())).filter(Boolean)}}return Array.isArray(r)?r.map((r=>r&&"object"==typeof r?r.name||JSON.stringify(r):String(r))):[]};
